-- Ticket reference IDs: HW-T<2 digits>ID<2 digits>, e.g. HW-T16ID24 (all capitals). Replaces the serial HM-000001 style.
-- Generated by the database so every insert path gets one. Rolls until it finds an unused ID. The two-digit/two-digit
-- format has 10,000 combinations; if it ever gets crowded (30 clashes in a row) the last part widens to 4 digits
-- (HW-T16ID2417) instead of failing the insert.
CREATE OR REPLACE FUNCTION gen_ticket_no() RETURNS TEXT AS $$
DECLARE v TEXT; i INT := 0;
BEGIN
  LOOP
    i := i + 1;
    v := 'HW-T' || lpad(floor(random() * 100)::int::text, 2, '0') || 'ID'
         || CASE WHEN i <= 30 THEN lpad(floor(random() * 100)::int::text, 2, '0')
                 ELSE lpad(floor(random() * 10000)::int::text, 4, '0') END;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM tickets WHERE ticket_no = v);
  END LOOP;
  RETURN v;
END $$ LANGUAGE plpgsql VOLATILE;

-- back-fill existing tickets (oldest first) with the new format
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT id FROM tickets ORDER BY created_at, id LOOP
    UPDATE tickets SET ticket_no = gen_ticket_no() WHERE id = r.id;
  END LOOP;
END $$;

ALTER TABLE tickets ALTER COLUMN ticket_no SET DEFAULT gen_ticket_no();
